// R1Twin game target. Written for UE 5.7; NOT YET COMPILED on this machine (see docs/ue5_setup.md).

using UnrealBuildTool;
using System.Collections.Generic;

public class R1TwinTarget : TargetRules
{
	public R1TwinTarget(TargetInfo Target) : base(Target)
	{
		Type = TargetType.Game;

		// "Latest" always exists; UE 5.7 templates spell out the concrete enum value
		// (BuildSettingsVersion.V6 / EngineIncludeOrderVersion.Unreal5_7 at the time of writing).
		// Replace with the concrete values once the project has been generated by the 5.7 editor.
		DefaultBuildSettings = BuildSettingsVersion.Latest;
		IncludeOrderVersion = EngineIncludeOrderVersion.Latest;

		ExtraModuleNames.AddRange(new string[] { "R1Twin" });
	}
}
